@let root = "/etc/dotfiles"
@destination = "${root}/tool"
@deploy = "copy"
@privilege = "system"
@sensitivity = "public"
@mode = "0644"
@owner = "root"
@group = "root"
@description = "Complete facet"
@theme = mocha

./config {
    @let target = "/etc/dotfiles/tool/config"
    @destination = $target
    @deploy = "copy"
    @privilege = "system"
    @sensitivity = "public"
    @mode = "0644"
    @owner = "root"
    @group = "root"
}
./generated { @deploy = "none", @expect = "directory" }

parent {
    @let package = "parent-package"
    @pkg = $package
    @installer = "cargo"
    @bin = "parent"
    @check = "command"
    @version = "1"
    @family = ["Parent Sans"]
    @service = "parent.service"
    @scope = "user"
    @path = "/var/lib/parent"
    @description = "Parent entity"
    child { @pkg = "child-package" }
    @font {
        @let font_package = "font-package"
        @key = hack_nerd_font
        @pkg = $font_package
        @installer = "brew-cask"
        @check = "font"
        @version = "1"
        @family = ["Hack Nerd Font Mono"]
        @description = "Nested font resource"
    }
}

@extend entity/parent {
    @let coordinate = "parent-extension"
    @pkg = $coordinate
    @installer = "cargo"
    @bin = "parent"
    @check = "command"
    @version = "2"
    @family = "Parent Sans"
    @service = "parent.service"
    @scope = "system"
    @path = "/var/lib/parent"
    @description = "Entity extension"
}
@extend font/hack_nerd_font {
    @let coordinate = "font-extension"
    @pkg = $coordinate
    @installer = "brew-cask"
    @check = "font"
    @version = "2"
    @family = "Hack Nerd Font Mono"
    @description = "Resource extension"
}
